import { Database } from "bun:sqlite";
import { expect, test } from "bun:test";
import { clashes, overlaps } from "../../src/loans/reserve";

function databaseWithOpenLoan(): Database {
  const db = new Database(":memory:");
  db.exec(
    "CREATE TABLE loans (id TEXT, item_id TEXT, out_date TEXT, due_date TEXT, returned_date TEXT)",
  );
  db.exec("CREATE TABLE reservations (id TEXT, item_id TEXT, from_date TEXT, to_date TEXT)");
  db.exec("INSERT INTO loans VALUES ('L-101', 'drill-01', '2026-03-06', '2026-03-13', NULL)");
  return db;
}

tool_input.command:
cat >> tests/loans/reserve.test.ts <<'EOF'

test("a booking that starts on the due date of an open loan clashes with it", () => {
  const db = databaseWithOpenLoan();
  const wanted = { from: "2026-03-13", to: "2026-03-15" };
  expect(clashes(db, "drill-01", wanted)).toEqual(["L-101"]);
});

test("two ranges that share only one date overlap", () => {
  expect(
    overlaps({ from: "2026-03-06", to: "2026-03-13" }, { from: "2026-03-13", to: "2026-03-15" }),
  ).toBe(true);
});
EOF
